///|
fn prefix() -> String { "Hello, " }
///|
pub fn greet(name : String) -> String { let greeting : String = prefix(); greeting + name }
///|
pub fn welcome(name : String, enabled : Bool) -> String { if enabled { greet(name) } else { "" } }

///|
test "UTF-16 and exact String equality" {
  assert_eq("".length(), 0)
  assert_eq("a😀b".length(), 4)
  assert_eq("é".length(), 1)
  assert_eq("e\u{301}".length(), 2)
  assert_eq("é" == "e\u{301}", false)
  assert_eq("😀" == "\u{1f600}", true)
  assert_eq("Hello, " + "Morphir", "Hello, Morphir")
  assert_eq(welcome("Morphir", true), "Hello, Morphir")
  assert_eq(welcome("Morphir", false), "")
  assert_eq("" + "😀", "😀")
}

///|
test "Shortlex source order differs from SDK lexical order" {
  assert_eq("b" < "aa", true)
  assert_eq("b".compare("aa"), -1)
  assert_eq("b".lexical_compare("aa"), 1)
  assert_eq(@sdk_string.compare(@sdk.Text::from_string("b"), @sdk.Text::from_string("aa")), @sdk.GT)
  assert_eq("😀" < "\u{e000}a", true)
  assert_eq("a😀b".compare("a😀b"), 0)
}

///|
test "Source slices clamp and trim split surrogate pairs inward" {
  let s = "a😀b"
  assert_eq(s[1:3].to_owned(), "😀")
  assert_eq(s[1:2].to_owned(), "")
  assert_eq(s[2:3].to_owned(), "")
  assert_eq(s[2:4].to_owned(), "b")
  assert_eq(s[-1:3].to_owned(), "a😀")
  assert_eq(s[4:1].to_owned(), "")
  assert_eq(s[-2147483648:2147483647].to_owned(), s)
  assert_eq(s[2147483647:2147483647].to_owned(), "")
  assert_eq("e\u{301}"[1:2].to_owned(), "\u{301}")
}

///|
test "SDK slice retains UTF-16 halves and uses negative offsets" {
  let s = @sdk.Text::from_string("a😀b")
  let high = @sdk_string.slice(1, 2, s)
  assert_eq(high.to_units(), [(55357).to_uint16()])
  let error = try { ignore(high.to_string()); false } catch { @sdk.UnrepresentableText(_) => true; _ => false }
  assert_true(error)
  assert_eq(@sdk_string.slice(-1, 3, s).to_units(), [])
  let low = @sdk.Text::from_units([(56832).to_uint16()])
  let error = try { ignore(low.to_string()); false } catch { @sdk.UnrepresentableText(_) => true; _ => false }
  assert_true(error)
}

///|
test "Pinned source predicate methods and ASCII-only case mappings" {
  assert_eq("".is_empty(), true)
  let receiver = "a😀b"
  let needle = "😀"
  assert_eq(receiver.contains(needle), true)
  assert_eq("a😀b".has_prefix("a"), true)
  assert_eq("a😀b".has_suffix("b"), true)
  assert_eq("Straße".to_upper(), "STRAßE")
  assert_eq(@sdk_string.to_upper(@sdk.Text::from_string("Straße")).to_string(), "STRASSE")
  assert_eq("ΟΣ".to_lower(), "ΟΣ")
  assert_eq(@sdk_string.to_lower(@sdk.Text::from_string("ΟΣ")).to_string(), "ος")
}

