///|
fn ty(name : String) -> @ir.Type raise { @ir.Type::Reference(@ir.TypeAttributes::default(), @ir.FQName::parse("morphir/SDK:" + name), []) }
///|
fn attrs(t : @ir.Type) -> @ir.ValueAttributes { { source: None, inferred_type: Some(t), extensions: Map([]), } }
///|
fn str(value : String) -> @ir.Value raise { @ir.Value::Literal(attrs(ty("string#string")), @ir.Literal::StringLiteral(value)) }
///|
fn number(n : String) -> @ir.Value raise { @ir.Value::Literal(attrs(ty("basics#int")), @ir.Literal::IntegerLiteral(n)) }
///|
fn call(name : String, args : Array[(@ir.Value, @ir.Type)], result : @ir.Type) -> @ir.Value raise {
  let mut signature = result
  for i = args.length()-1; i >= 0; i = i-1 { signature = @ir.Type::Function(@ir.TypeAttributes::default(), args[i].1, signature) }
  let mut value = @ir.Value::Reference(attrs(signature), @ir.FQName::parse("morphir/SDK:" + name))
  for (arg, _) in args {
    guard signature is Function(_, _, output) else { fail("function") }
    signature = output
    value = @ir.Value::Apply(attrs(output), value, arg)
  }
  value
}
///|
fn shortlex(a : String, b : String) -> @ir.Value raise {
  let text = ty("string#string"); let int = ty("basics#int"); let bool = ty("basics#bool")
  let x = call("string#length", [(str(a), text)], int)
  let y = call("string#length", [(str(b), text)], int)
  @ir.Value::IfThenElse(attrs(bool), call("basics#equal", [(x,int),(y,int)], bool),
    call("basics#less-than", [(str(a),text),(str(b),text)], bool),
    call("basics#less-than", [(x,int),(y,int)], bool))
}
///|
fn observed(value : @scheme.Value) -> Json raise {
  match value {
    Text(s) => { "text": s }
    Boolean(b) => { "bool": b }
    Number(n) => { "int": @scheme.value_to_string(@scheme.Number(n)) }
    Tagged("sdk-text", [Vector(xs)]) => { "units": xs.map(x => @scheme.value_to_string(x)) }
    _ => fail("unexpected observation")
  }
}
///|
fn probe() -> Json raise {
  let text = ty("string#string"); let int = ty("basics#int"); let bool = ty("basics#bool")
  let cases : Array[(String, @ir.Type, @ir.Value, Json)] = [
    ("append-empty",text,call("string#append",[(str(""),text),(str("😀"),text)],text),{"text":"😀"}),
    ("greeting",text,call("string#append",[(str("Hello, "),text),(str("Morphir"),text)],text),{"text":"Hello, Morphir"}),
    ("append-unicode",text,call("string#append",[(str("a😀"),text),(str("e\u{301}"),text)],text),{"text":"a😀e\u{301}"}),
    ("equal-normalization",bool,call("basics#equal",[(str("é"),text),(str("e\u{301}"),text)],bool),{"bool":false}),
    ("equal-emoji",bool,call("basics#equal",[(str("😀"),text),(str("\u{1f600}"),text)],bool),{"bool":true}),
    ("length-utf16",int,call("string#length",[(str("a😀b"),text)],int),{"int":"4"}),
    ("sdk-lexical-order",bool,call("basics#less-than",[(str("b"),text),(str("aa"),text)],bool),{"bool":false}),
    ("source-shortlex-order",bool,shortlex("b","aa"),{"bool":true}),
    ("source-shortlex-unicode",bool,shortlex("😀","\u{e000}a"),{"bool":true}),
    ("sdk-surrogate-half",text,call("string#slice",[(number("1"),int),(number("2"),int),(str("a😀b"),text)],text),{"units":["55357"]}),
    ("sdk-negative-offset",text,call("string#slice",[(number("-1"),int),(number("3"),int),(str("a😀b"),text)],text),{"text":""}),
    ("is-empty",bool,call("string#is-empty",[(str(""),text)],bool),{"bool":true}),
    ("contains-emoji",bool,call("string#contains",[(str("😀"),text),(str("a😀b"),text)],bool),{"bool":true}),
    ("prefix",bool,call("string#starts-with",[(str("a"),text),(str("a😀b"),text)],bool),{"bool":true}),
    ("suffix",bool,call("string#ends-with",[(str("b"),text),(str("a😀b"),text)],bool),{"bool":true}),
  ]
  let values : Map[@ir.Name, @ir.AccessControlled[@ir.Documented[@ir.ValueDefinition]]] = Map([])
  for (id, t, expr, _) in cases {
    values[@ir.Name::parse(id)] = { access: @ir.Access::Public, value: {doc:None,value:@ir.ValueDefinition::ExpressionBody([],t,expr)}, }
  }
  let ir = @ir.IRFile::new(@ir.Distribution::Library(@ir.Path::parse("strings"),Map([]),{modules:Map::from_array([(@ir.Path::parse("main"),{access:@ir.Access::Public,value:{types:Map([]),values,doc:None}})])}))
  let results : Array[Json] = []
  for (id, _, _, expected) in cases {
    let result = observed(@backend.run_file(ir,@ir.FQName::parse("strings:main#"+id),[]))
    assert_eq(result,expected,msg=id)
    results.push({"id":id,"expected":expected,"scheme":result})
  }
  let output = @generator.generate(@generator.Input::new("strings-design-probes", ir))
  let sources = [
    "pub fn greet(name : String) -> String { let prefix : String = \"Hello, \"; prefix + name }",
    "pub fn empty(s : String) -> Bool { s.is_empty() }",
    "pub fn contains(s : String) -> Bool { s.contains(\"😀\") }",
    "pub fn slice(s : String, a : Int32, b : Int32) -> String { s[a:b].to_owned() }",
  ]
  let parses = sources.map(source => {
    let (_, reports) = @parser.parse_string(source)
    assert_eq(reports.length(),0)
    let refusal = try { ignore(@frontend.compile_library({unit_id:"probe",package_name:"strings",module_name:"main",source})); "unexpected-success" } catch { @frontend.Invalid(d) => d.code; error => raise error }
    assert_eq(refusal,"moonbit_frontend.unsupported_type")
    ({"source":source,"parserAccepted":true,"currentFrontend":refusal}:Json)
  })
  ({"scope":"Design probes: original source/core and hand-authored typed IR; not String source frontend qualification", "cases":results,"syntax":parses,"symbols":output.symbols.map(s => ({"fqname":s.fqname,"name":s.generated_name}:Json)),"artifacts":output.artifacts.map(a => ({"path":a.path,"content":match a.content {Text(s)=>Json::string(s);Binary(b)=>Json::array(b.to_array().map(x=>Json::number(x.to_int().to_double())))}}:Json))}:Json)
}

