```bash
moon fmt
git add apps/morphir-workbench/browser/project-io.js apps/morphir-workbench/browser/project-io.test.js apps/morphir-workbench/browser/main.mbt apps/morphir-workbench/browser/storage_wbtest.mbt apps/morphir-workbench/scripts/elm-workflow.js apps/morphir-workbench/README.md
git commit -m "feat(workbench): keep each language's project in browser storage"
```

