use morphir_extension_sdk::claims::CapabilityClaimSet;
use morphir_extension_sdk::protocol::{InitializeParams, InitializeResult};
use morphir_extension_sdk::{Artifact, CompileResult, ExtensionCapabilities, ExtensionInfo, GenerateRequest};
use morphir_host::Negotiated;
use serde_json::{json, Value};

fn main() {
    let mut observations = Vec::new();
    let mut record = |name: &str, observed: bool, expected: bool| {
        assert_eq!(observed, expected, "{name}");
        observations.push(json!({"case":name,"observed":observed,"expected":expected,"passed":true}));
    };
    let frontend = json!({
        "languages":[{"id":"moonbit","fileExtensions":[".mbt"]}],
        "irVersions":["4"],"compile":true,"incremental":false,"fragments":false,
        "profiles":[{"id":"moonbit-model-bool-library-v1","unitFormats":["ion-binary"]}]
    });
    let unit_formats = json!({"contracts":["morphir-pipeline-v1"],"codecs":["ion-binary"]});
    let capabilities = json!({"frontend":frontend,"unitTransport":unit_formats});
    let claim_json = json!({
        "claimsVersion":"0.1.0-draft.2","protocolVersions":["0.1"],
        "extension":{"id":"probe","name":"Probe","version":"0.0.0","types":["frontend"]},
        "capabilities":capabilities
    });
    let claims: CapabilityClaimSet = serde_json::from_value(claim_json.clone()).unwrap();
    let claim_roundtrip = serde_json::to_value(&claims).unwrap();
    record("claim_set_preserves_unknown_profile_members", claim_roundtrip["capabilities"]["frontend"]["profiles"] == frontend["profiles"], true);
    record("claim_set_preserves_unknown_unit_capability", claim_roundtrip["capabilities"]["unitTransport"] == unit_formats, true);

    let typed_capabilities: ExtensionCapabilities = serde_json::from_value(capabilities.clone()).unwrap();
    let cap_roundtrip = serde_json::to_value(&typed_capabilities).unwrap();
    record("typed_top_level_extra_capability_survives", cap_roundtrip["unitTransport"] == unit_formats, true);
    record("typed_nested_frontend_profile_survives", cap_roundtrip["frontend"].get("profiles").is_some(), false);

    let mut leaf_critical = claim_json.clone();
    leaf_critical["critical"] = json!(["capabilities.unitTransport"]);
    let leaf_result = serde_json::from_value::<CapabilityClaimSet>(leaf_critical);
    record("unknown_exact_critical_leaf_is_rejected", leaf_result.is_err(), true);
    let mut parent_critical = claim_json;
    parent_critical["critical"] = json!(["capabilities"]);
    record("known_parent_critical_accepts_unknown_child", serde_json::from_value::<CapabilityClaimSet>(parent_critical).is_ok(), true);

    record("session_may_omit_unselected_claims", claims.check_session("0.1", &claims.extension, &serde_json::Map::new()).is_ok(), true);

    let init_params: InitializeParams = serde_json::from_value(json!({
        "protocolVersions":["0.1"],"host":{"kind":"cli","name":"probe","version":"0.0.0"},
        "capabilities":{"unitTransport":unit_formats}
    })).unwrap();
    record("typed_init_host_payload_offer_survives", serde_json::to_value(init_params).unwrap().get("capabilities").is_some(), false);
    let initialized: InitializeResult = serde_json::from_value(json!({
        "protocolVersion":"0.1","extension":claims.extension,"capabilities":capabilities
    })).unwrap();
    let initialized_roundtrip = serde_json::to_value(initialized).unwrap();
    record("initialized_top_level_unit_extra_survives", initialized_roundtrip["capabilities"]["unitTransport"] == unit_formats, true);
    record("initialized_nested_profile_survives", initialized_roundtrip["capabilities"]["frontend"].get("profiles").is_some(), false);

    let compiled: CompileResult = serde_json::from_value(json!({
        "success":true,"unit":{"contract":"morphir-pipeline-v1"},"diagnostics":[]
    })).unwrap();
    let compiled_roundtrip = serde_json::to_value(compiled).unwrap();
    record("unit_only_compile_success_survives_as_unit", compiled_roundtrip.get("unit").is_some(), false);
    record("legacy_generate_accepts_unit_instead_of_ir", serde_json::from_value::<GenerateRequest>(json!({
        "unit":{"contract":"morphir-pipeline-v1"},"target":"moonbit","options":{}
    })).is_ok(), false);

    let negotiated = Negotiated::new("0.1".into(), ExtensionInfo::default(), ExtensionCapabilities::default(), false);
    record("unknown_candidate_unit_method_is_explicitly_gated", !negotiated.supports_method("morphir.backend.generateUnit"), false);
    let artifact: Artifact = serde_json::from_value(json!({"path":"symbols.ionb","content":"4AEA6g==","binary":true})).unwrap();
    record("existing_binary_artifact_roundtrips", serde_json::to_value(artifact).unwrap()==json!({"path":"symbols.ionb","content":"4AEA6g==","binary":true}), true);

    println!("{}", serde_json::to_string_pretty(&json!({
        "profile":"morphir-mep-analysis-sdk-probe-v1",
        "sourceRevision":"6a481ec17cf75d889ad363b008ece2ba0ea6e05f",
        "count":observations.len(),"allPassed":true,"observations":observations,
        "scope":"Actual pinned SDK and transport-neutral host types/admission helpers. Candidate field and method names are probes, not implemented contracts. No process/Extism activation, installed integration, profile negotiation or complete metadata preservation is claimed."
    })).unwrap());
}

```

