///|
fn compile_one(content : String) -> @ir.IRFile raise @frontend.ElmFailed {
  @frontend.compile_project([{ path: "My/Pkg/A.elm", content }], "My.Pkg", ["A"])
}

///|
fn a_value(file : @ir.IRFile, name : String) -> @ir.ValueDefinition {
  guard file.distribution is Library(_, _, def) else { abort("library") }
  def.modules[@ir.Path::parse("a") catch { _ => panic() }].value.values[
    @ir.Name::parse(name) catch { _ => panic() }
  ].value.value
}

///|
/// The number of value and pattern nodes without an inferred type, let definitions included.
fn untyped(v : @ir.Value) -> Int {
  let sum = (items : Array[@ir.Value]) => items.fold(init=0, (n, x) => n + untyped(x))
  let in_definition = (d : @ir.ValueDefinition) => match d {
    ExpressionBody(_, _, body) => untyped(body)
    _ => 0
  }
  match v {
    Literal(a, _) | Constructor(a, _) | Variable(a, _) | Reference(a, _) | FieldFunction(a, _) | Unit(a) | Hole(a, _, _) =>
      missing(a)
    Tuple(a, items) | List(a, items) => missing(a) + sum(items)
    Record(a, fields) => missing(a) + sum(fields.values().collect())
    Field(a, r, _) => missing(a) + untyped(r)
    Apply(a, f, x) => missing(a) + untyped(f) + untyped(x)
    Lambda(a, p, b) => missing(a) + untyped_pattern(p) + untyped(b)
    LetDefinition(a, _, d, i) => missing(a) + in_definition(d) + untyped(i)
    LetRecursion(a, defs, i) =>
      missing(a) + defs.values().fold(init=0, (n, d) => n + in_definition(d)) + untyped(i)
    Destructure(a, p, x, i) => missing(a) + untyped_pattern(p) + untyped(x) + untyped(i)
    IfThenElse(a, c, t, e) => missing(a) + untyped(c) + untyped(t) + untyped(e)
    PatternMatch(a, s, cases) =>
      missing(a) + untyped(s) + cases.fold(init=0, (n, c) => n + untyped_pattern(c.0) + untyped(c.1))
    UpdateRecord(a, r, fields) => missing(a) + untyped(r) + sum(fields.values().collect())
  }
}

///|
fn untyped_pattern(p : @ir.Pattern) -> Int {
  match p {
    WildcardPattern(a) | EmptyListPattern(a) | LiteralPattern(a, _) | UnitPattern(a) => missing(a)
    AsPattern(a, inner, _) => missing(a) + untyped_pattern(inner)
    TuplePattern(a, items) | ConstructorPattern(a, _, items) =>
      missing(a) + items.fold(init=0, (n, x) => n + untyped_pattern(x))
    HeadTailPattern(a, h, t) => missing(a) + untyped_pattern(h) + untyped_pattern(t)
  }
}

///|
fn missing(a : @ir.ValueAttributes) -> Int {
  if a.inferred_type is None { 1 } else { 0 }
}

