```moonbit
///|
pub fn value_attributes(range : @ast.Range) -> @ir.ValueAttributes {
  {
    ..@ir.ValueAttributes::default(),
    source: Some({
      start_line: range.start.row,
      start_column: range.start.column,
      end_line: range.end.row,
      end_column: range.end.column,
    }),
  }
}

///|
/// The state of lowering one top-level declaration: the scope, the local names (one frame per binding form) and
/// the next placeholder number, shared by the declaration and its lets.
priv struct Lowering {
  scope : @resolve.Scope
  locals : Array[Map[String, Bool]]
  placeholders : Ref[Int]
}

///|
fn Lowering::is_local(self : Lowering, name : String) -> Bool {
  self.locals.iter().any(frame => frame.contains(name))
}

///|
fn Lowering::placeholder(self : Lowering) -> @ir.Type {
  let n = self.placeholders.val
  self.placeholders.val = n + 1
  placeholder(n)
}

///|
fn starts_upper(name : String) -> Bool {
  match name.get_char(0) {
    Some(c) => c >= 'A' && c <= 'Z'
    None => false
  }
}

///|
pub fn lower_value_definition(
  scope : @resolve.Scope,
  f : @ast.Function,
) -> (String, @ir.ValueDefinition) raise LowerError {
  let lowering : Lowering = { scope, locals: [], placeholders: Ref(0) }
  let declaration = f.declaration.value
  let (arguments, body) = arguments_and_body(declaration)
  let frame : Map[String, Bool] = Map([])
  let patterns = arguments.map(a => lowering.pattern(a, frame))
  let inputs : Array[(@ir.Name, @ir.Type)] = []
  let mut rest = f.signature.map(s => s.value.type_annotation)
  let mut lifted = 0
  while lifted < arguments.length() {
    guard arguments[lifted].value is VarPattern(name) else { break }
    match rest {
      None => inputs.push((@mapping.elm_name(name), lowering.placeholder()))
      Some(annotation) => {
        guard function_parts(annotation) is Some((argument, result)) else { break }
        inputs.push((@mapping.elm_name(name), lower_type(scope, argument, None)))
        rest = Some(result)
      }
    }
    lifted += 1
  }
  let output = match rest {
    None => lowering.placeholder()
    Some(annotation) => lower_type(scope, annotation, None)
  }
  lowering.locals.push(frame)
  let mut value = lowering.expression(body)
  ignore(lowering.locals.pop())
  for i = arguments.length() - 1; i >= lifted; i = i - 1 {
    value = Lambda(value_attributes(arguments[i].range), patterns[i], value)
  }
  (declaration.name.value, ExpressionBody(inputs, output, value))
}
```

`arguments_and_body(declaration)` returns the declaration arguments followed by the arguments of every leading lambda of the body (looking through any number of `ParenthesizedExpression`), and the body after the last of them. `function_parts` is the existing helper in `signatures.mbt` (single-item `Tupled` peel, then `FunctionTypeAnnotation`); make it shared. The `Lambda` attributes may use each argument's range: they are not compared. `Lowering::expression` matches every `@ast.Expression` variant: the arms of this task as the rules above say, and `LowerError("elm.unsupported", "<kind> is not lowered yet", Some(node.range))` for the rest. `Lowering::pattern` is in `patterns.mbt`, by confirmed fact 6; `VarPattern(n)` binds `n` in the frame and gives `AsPattern(a, WildcardPattern(a), elm_name(n))`; `AsPattern(inner, n)` binds `n.value`; `ListPattern(items)` folds right into `HeadTailPattern` ending in `EmptyListPattern`.

