```moonbit
// Runs pinned morphir-elm make on every project in pkgs/morphir-elm/conformance/projects, writes each
// expected/morphir-ir.json, and regenerates pkgs/morphir-elm/conformance/parity_data.mbt.

///|
import {
  "moonbitlang/async@0.22.1",
  "moonbitlang/async@0.22.1/fs",
  "moonbitlang/async@0.22.1/process",
  "moonbitlang/async@0.22.1/stdio",
  "moonbitlang/x@0.5.5/sys",
}

///|
let root : String = "pkgs/morphir-elm/conformance"

///|
async fn run(program : String, args : Array[String]) -> Unit {
  let code = @process.run(program, args, stdout=@stdio.stdout, stderr=@stdio.stderr)
  if code != 0 {
    @sys.exit(if code > 0 { code } else { 1 })
  }
}

///|
async fn elm_sources(dir : String, prefix : String, out : Array[(String, String)]) -> Unit {
  for entry in @fs.readdir(dir, sort=true) {
    let path = dir + "/" + entry
    match @fs.kind(path) {
      Directory => elm_sources(path, prefix + entry + "/", out)
      _ =>
        if entry.has_suffix(".elm") {
          out.push((prefix + entry, @fs.read_file(path).text()))
        }
    }
  }
}

///|
fn quoted(text : String) -> String {
  Json::string(text).stringify()
}

///|
async fn main {
  run("npm", ["ci", "--prefix", "pkgs/morphir-elm/scripts"])
  let make = "pkgs/morphir-elm/scripts/node_modules/.bin/morphir-elm"
  let lines = [
    "// GENERATED by scripts/elm-parity-refresh.mbtx. Do not edit.",
    "// Sources: pkgs/morphir-elm/conformance/projects. Expected IR: morphir-elm 2.100.0.",
    "",
    "///|",
    "fn parity_projects() -> Array[ParityProject] {",
    "  [",
  ]
  for name in @fs.readdir(root + "/projects", sort=true) {
    let dir = root + "/projects/" + name
    @fs.mkdir(dir + "/expected", recursive=true)
    run(make, ["make", "-p", dir, "-o", dir + "/expected/morphir-ir.json", "-i"])
    if @fs.exists(dir + "/morphir-hashes.json") {
      @fs.remove(dir + "/morphir-hashes.json")
    }
    let config = @json.parse(@fs.read_file(dir + "/morphir.json").text()) catch {
      _ => { @stdio.stderr.write("bad morphir.json in \{dir}\n"); @sys.exit(1); panic() }
    }
    guard config is Object(fields) &&
      fields.get("name") is Some(String(package_name)) &&
      fields.get("exposedModules") is Some(Array(exposed)) else {
      @stdio.stderr.write("morphir.json in \{dir} needs name and exposedModules\n")
      @sys.exit(1)
      panic()
    }
    let source_dir = match fields.get("sourceDirectory") { Some(String(s)) => s; _ => "src" }
    let sources : Array[(String, String)] = []
    elm_sources(dir + "/" + source_dir, "", sources)
    let expected = @fs.read_file(dir + "/expected/morphir-ir.json").text()
    lines.push("    {")
    lines.push("      name: \{quoted(name)},")
    lines.push("      package_name: \{quoted(package_name)},")
    lines.push("      exposed: [\{exposed.map(e => e.stringify()).join(", ")}],")
    lines.push("      sources: [")
    for s in sources {
      lines.push("        (\{quoted(s.0)}, \{quoted(s.1)}),")
    }
    lines.push("      ],")
    lines.push("      expected: \{quoted(expected)},")
    lines.push("    },")
  }
  lines.push("  ]")
  lines.push("}")
  @fs.write_file(root + "/parity_data.mbt", lines.join("\n") + "\n")
  run("moon", ["fmt"])
}
```

(Adjust to the async API of this toolchain: `@fs.kind` returns a `FileKind`; `read_file(...).text()` is how other scripts read text; `@json.parse` comes from `moonbitlang/core/json`, available without import in a script, or add it. Running `moon fmt` at the end keeps `moon fmt --check` clean.)

