`errors.mbt`:

```moonbit
///|
pub(all) suberror SpecError {
  SpecError(line~ : Int, column~ : Int, message~ : String)
} derive(Eq, Debug)

///|
priv struct Context {
  source : String
  package_name : @ir.Path
  module : @ir.Path
}

///|
fn[T] Context::fail(self : Context, at : @scheme.Located, message : String) -> T raise SpecError {
  let (line, column) = @scheme.line_column(self.source, at.start)
  raise SpecError(line~, column~, message~)
}
```

`names.mbt`:

```moonbit
///|
fn symbol(at : @scheme.Located) -> String? {
  match at.datum {
    Symbol(text) => Some(text)
    _ => None
  }
}

///|
fn read_name(ctx : Context, at : @scheme.Located) -> @ir.Name raise SpecError {
  guard symbol(at) is Some(text) else { ctx.fail(at, "expected a name") }
  let name = @ir.Name::parse(text) catch {
    _ => ctx.fail(at, "name `\{text}` is not canonical (use `\{suggest(text)}`)")
  }
  if name.to_canonical() != text {
    ctx.fail(at, "name `\{text}` is not canonical (use `\{name.to_canonical()}`)")
  }
  name
}

///|
/// camelCase to canonical words for error hints only.
fn suggest(text : String) -> String {
  let out = StringBuilder::new()
  for i, c in text.iter().collect() {
    if c >= 'A' && c <= 'Z' && i > 0 {
      out.write_char('-')
      out.write_char((c.to_int() + 32).unsafe_to_char())
    } else {
      out.write_char(c)
    }
  }
  out.to_string()
}

///|
fn read_reference(ctx : Context, at : @scheme.Located, text : String) -> @ir.FQName raise SpecError {
  let full = if text.contains(":") {
    text
  } else {
    ctx.package_name.to_canonical() + ":" + text
  }
  let name = @ir.FQName::parse(full) catch { _ => ctx.fail(at, "`\{text}` is not a reference") }
  if name.to_canonical() != full {
    ctx.fail(at, "reference `\{text}` is not canonical (use `\{name.to_canonical()}`)")
  }
  name
}

///|
fn class_of(name : @ir.Name) -> String? {
  let text = name.to_canonical()
  for class in ["compappend", "appendable", "comparable", "number"] {
    if text.has_prefix(class) {
      return Some(class)
    }
  }
  None
}
```

`types.mbt`:

```moonbit
///|
fn type_attrs() -> @ir.TypeAttributes {
  { source: None, constraints: Map([]), extensions: Map([]) }
}

///|
fn variable(name : @ir.Name) -> @ir.Type {
  let constraints : Map[String, @ir.Data] = Map([])
  if class_of(name) is Some(class) {
    constraints["typeclass"] = Text(class)
  }
  Variable({ ..type_attrs(), constraints, }, name)
}

///|
fn check_head(ctx : Context, at : @scheme.Located, head : String) -> Unit raise SpecError {
  if head.has_suffix("!") {
    ctx.fail(at, "`\{head}` is reserved for macros")
  }
}

///|
fn read_type(ctx : Context, at : @scheme.Located) -> @ir.Type raise SpecError {
  match at.datum {
    Symbol(text) =>
      if text.contains("#") {
        Reference(type_attrs(), read_reference(ctx, at, text), [])
      } else {
        check_head(ctx, at, text)
        variable(read_name(ctx, at))
      }
    Sequence([], None) => Unit(type_attrs())
    Sequence(_, None) => {
      let head = at.children[0]
      let rest = at.children[1:].to_array()
      guard symbol(head) is Some(text) else { ctx.fail(at, "expected a type form") }
      check_head(ctx, at, text)
      match text {
        "->" => {
          if rest.length() < 2 {
            ctx.fail(at, "a function type needs at least two types")
          }
          let types = rest.map(t => read_type(ctx, t))
          let mut result = types[types.length() - 1]
          for i = types.length() - 2; i >= 0; i = i - 1 {
            result = Function(type_attrs(), types[i], result)
          }
          result
        }
        "tuple" => {
          if rest.length() < 2 {
            ctx.fail(at, "a tuple needs at least two types")
          }
          Tuple(type_attrs(), rest.map(t => read_type(ctx, t)))
        }
        "record" => {
          let (extension, field_forms) = match rest {
            [first, .. tail] if symbol(first) is Some(_) => (Some(read_name(ctx, first)), tail.to_array())
            _ => (None, rest)
          }
          let fields : Map[@ir.Name, @ir.Type] = Map([])
          for field in field_forms {
            guard field.children is [name_form, type_form] else {
              ctx.fail(field, "a record field is (name type)")
            }
            let name = read_name(ctx, name_form)
            if fields.contains(name) {
              ctx.fail(field, "duplicate field `\{name.to_canonical()}`")
            }
            fields[name] = read_type(ctx, type_form)
          }
          match extension {
            Some(r) => ExtensibleRecord(type_attrs(), r, fields)
            None => Record(type_attrs(), fields)
          }
        }
        _ if text.contains("#") =>
          Reference(type_attrs(), read_reference(ctx, head, text), rest.map(t => read_type(ctx, t)))
        _ => ctx.fail(at, "unknown type form `\{text}`")
      }
    }
    _ => ctx.fail(at, "expected a type")
  }
}

///|
pub fn read_type_text(
  text : String,
  package_name~ : String,
  module~ : String,
) -> @ir.Type raise SpecError {
  let forms = @scheme.parse_program_located(text) catch {
    Syntax(message, offset) => {
      let (line, column) = @scheme.line_column(text, offset)
      raise SpecError(line~, column~, message~)
    }
    e => raise SpecError(line=1, column=1, message=e.to_string())
  }
  guard forms is [form] else { raise SpecError(line=1, column=1, message="expected one type") }
  let ctx = {
    source: text,
    package_name: @ir.Path::parse(package_name) catch { _ => panic() },
    module: @ir.Path::parse(module) catch { _ => panic() },
  }
  read_type(ctx, form)
}
```

Adapt the syntax to the compiler where needed: array patterns and the `.. tail` rest form. Keep the messages
exactly as the tests expect.

