fn elm_generation(
  unit : @data.IRUnit,
  options : Json,
  cancelled : () -> Bool,
) -> GenerationBatch raise {
  let output = @elm.generate(unit.id, unit.distribution, @elm.Options::from_json(options), cancelled~) catch {
