  "scope": "parser feasibility only; no Morphir frontend implemented",
  "testsPerTarget": 6,
  "targets": [
    "js",
    "native",
    "wasm",
    "wasm-gc"
  ],
  "compilerNegativeCheck": {
    "target": "js",
    "exit": 255,
    "code": 4014
  },
  "observations": [
    "untyped parser accepts type-invalid Bool body",
    "syntax recovery emits diagnostics",
    "mutable syntax parses without semantic restriction",
    "Boolean seed truth table passes",
    "machine Int32 wraps max+1 to min"
  ],
  "probeSourceSha256": "0dd7130b7e217d3044a62b663f6303c575fdb784ed85ded6e627b90ee908c6ff",
  "compilerIdentity": "5dd098f0bf7b7756d02ba1c5668d77ebf3feb21aca49872c23adfc7cbf11e5ed",
